mapper.select:
SELECT s.sample_no, s.sample_name, DATE_FORMAT(s.sampling_date, '%Y.%m.%d') AS sampling_date, i.basis_code, i.item_name, i.unit, i.std_value, COALESCE(r.test_value, '') AS test_value, r.conclusion, s.task_no FROM sample_info s JOIN sample_item i ON i.sample_id = s.id AND i.deleted = 0 LEFT JOIN sample_result r ON r.sample_item_id = i.id AND r.deleted = 0 WHERE s.deleted = 0 AND s.status >= 80
AND s.task_no = #{taskNo}
ORDER BY s.id, i.item_order

SELECT s.sample_no, s.sample_name, s.client_name, s.task_no, i.item_order, i.item_name, i.methods, i.basis_code, i.std_value, i.unit, i.lower_limit, s.sample_state FROM sample_item i JOIN sample_info s ON s.id = i.sample_id AND s.deleted = 0 WHERE i.deleted = 0 AND s.status >= 40
AND i.tester_no = #{testerNo}
ORDER BY s.id, i.item_order
